1	# Fix the two data.error lines that the first (order-buggy) pass got wrong.
2	# Line-based, with an ASCII anchor check so we never touch the wrong line.
3	def T(*cps):
4	    return "".join(chr(c) for c in cps)
5	
6	ERROR   = T(0x0e01,0x0e40,0x0e34,0x0e14,0x0e02,0x0e49,0x0e2d,0x0e1e,0x0e34,0x0e14,0x0e1e,0x0e25,0x0e32,0x0e14)
7	DL_FAIL = T(0x0e23,0x0e40,0x0e34,0x0e48,0x0e21,0x0e14,0x0e32,0x0e27,0x0e19,0x0e42,0x0e2b,0x0e25,0x0e2d,0x0e14,0x0e21,0x0e44,0x0e21,0x0e48,0x0e2a,0x0e33,0x0e23,0x0e40,0x0e08)
8	
9	lines = open("static/app.js", encoding="utf-8").read().split("\n")
10	
11	def set_str(lineno, anchor, newstr):
12	    line = lines[lineno - 1]
13	    if anchor not in line:
14	        print(f"SKIP L{lineno}: anchor {anchor!r} not on line -> {line.strip()[:50]!r}")
15	        return
16	    i = line.find('"')
17	    j = line.find('"', i + 1)
18	    lines[lineno - 1] = line[:i + 1] + newstr + line[j:]
19	    print(f"OK   L{lineno}")
20	
21	set_str(74, "data.error ||", ERROR)
22	set_str(189, "data.error ||", DL_FAIL)
23	
24	open("static/app.js", "w", encoding="utf-8").write("\n".join(lines))
25	
26	# verify both lines now hold the intended code points
27	def cps(x): return " ".join(f"{ord(c):04x}" for c in x)
28	for n in (74, 189):
29	    import re
30	    m = re.search(r'"([^"]*)"', lines[n - 1])
31	    print(f"L{n} -> {cps(m.group(1))}")
32	print("done")
