1	// YT Downloader — frontend logic
2	const $ = (id) => document.getElementById(id);
3	
4	const els = {
5	  url: $("url"),
6	  checkBtn: $("checkBtn"),
7	  urlErr: $("urlErr"),
8	  infoCard: $("infoCard"),
9	  infoLoading: $("infoLoading"),
10	  infoBody: $("infoBody"),
11	  thumb: $("thumb"),
12	  vTitle: $("vTitle"),
13	  vUp: $("vUp"),
14	  vDur: $("vDur"),
15	  playlistList: $("playlistList"),
16	  optCard: $("optCard"),
17	  typeSeg: $("typeSeg"),
18	  qualityField: $("qualityField"),
19	  bitrateField: $("bitrateField"),
20	  quality: $("quality"),
21	  bitrate: $("bitrate"),
22	  dlBtn: $("dlBtn"),
23	  progCard: $("progCard"),
24	  progText: $("progText"),
25	  progPct: $("progPct"),
26	  barWrap: $("barWrap"),
