33	const CHECK_LABEL = els.checkBtn.textContent; // preserve original label
34	let currentType = "video";
35	let pollTimer = null;
36	
37	function fmtDuration(s) {
38	  if (!s && s !== 0) return "";
39	  s = Math.round(s);
40	  const h = Math.floor(s / 3600);
41	  const m = Math.floor((s % 3600) / 60);
42	  const sec = s % 60;
43	  const mm = String(m).padStart(2, "0");
44	  const ss = String(sec).padStart(2, "0");
45	  return h ? `${h}:${mm}:${ss}` : `${m}:${ss}`;
46	}
47	
48	function show(el, on) { el.classList.toggle("hidden", !on); }
49	
50	function setUrlError(msg) {
51	  els.urlErr.textContent = msg || "";
52	  show(els.urlErr, !!msg);
53	}
54	
55	async function checkInfo() {
56	  const url = els.url.value.trim();
57	  if (!url) return;
58	
59	  setUrlError("");
60	  els.checkBtn.disabled = true;
61	  els.checkBtn.innerHTML = '<span class="spinner" aria-hidden="true"></span>';
62	  hideProgress();
63	
64	  // show card + skeleton while fetching
65	  show(els.infoCard, true);
66	  show(els.infoLoading, true);
67	  show(els.infoBody, false);
68	  show(els.playlistList, false);
69	  show(els.optCard, false);
70	
71	  try {
72	    const res = await fetch("/api/info?url=" + encodeURIComponent(url));
73	    const data = await res.json();
74	    if (!res.ok) throw new Error(data.error || "รเิ่มดาวนโหลอดมไม่สำรเจ");
75	
76	    show(els.infoLoading, false);
77	    renderInfo(data);
78	  } catch (e) {
79	    show(els.infoCard, false);
80	    setUrlError(e.message);
81	  } finally {
82	    els.checkBtn.disabled = false;
83	    els.checkBtn.textContent = CHECK_LABEL;
84	  }
85	}
86	
87	function renderInfo(data) {
88	  show(els.infoLoading, false);
89	  show(els.infoBody, true);
90	  show(els.optCard, true);
91	  els.errMsg.textContent = "";
92	  show(els.errMsg, false);
93	
94	  if (data.is_playlist) {
95	    show(els.thumb, false);
96	    els.vTitle.textContent = data.title || "Playlist";
97	    els.vUp.textContent = `${data.count} คลิปใน playlist`;
98	    els.vDur.textContent = "";
99	    els.playlistList.innerHTML = "";
100	    (data.entries || []).forEach((e) => {
101	      const li = document.createElement("li");
102	      const t = document.createElement("span");
103	      t.className = "pl-title";
104	      t.textContent = e.title || "(มไมมีชื่)";
105	      const d = document.createElement("span");
106	      d.className = "pl-dur";
107	      d.textContent = fmtDuration(e.duration);
108	      li.append(t, d);
109	      els.playlistList.appendChild(li);
110	    });
111	    show(els.playlistList, true);
112	    // playlist: ไมใหเลือกความละเอียดรายคลิป
113	    show(els.qualityField, false);
114	    show(els.bitrateField, currentType === "mp3");
115	  } else {
116	    show(els.playlistList, false);
117	    show(els.thumb, true);
118	    els.thumb.src = data.thumbnail || "";
119	    els.vTitle.textContent = data.title || "";
120	    els.vUp.textContent = data.uploader || "";
121	    els.vDur.textContent = fmtDuration(data.duration);
122	
123	    // เติมตัวเลือกความละเอียด
124	    els.quality.innerHTML = "";
125	    const quals = data.qualities || [];
126	    if (quals.length) {
127	      quals.forEach((q) => {
128	        const o = document.createElement("option");
129	        o.value = q;
130	        o.textContent = q >= 1080 ? `${q}p (Full HD+)` : `${q}p`;
131	        els.quality.appendChild(o);
132	      });
133	    } else {
134	      const o = document.createElement("option");
135	      o.value = "";
136	      o.textContent = "สุงสุด";
137	      els.quality.appendChild(o);
138	    }
139	    show(els.qualityField, currentType === "video");
140	    show(els.bitrateField, currentType === "mp3");
141	  }
142	}
143	
144	function setType(type) {
145	  currentType = type;
146	  [...els.typeSeg.children].forEach((b) => {
147	    const on = b.dataset.type === type;
148	    b.classList.toggle("active", on);
149	    b.setAttribute("aria-selected", on ? "true" : "false");
150	  });
151	  show(els.qualityField, type === "video");
152	  show(els.bitrateField, type === "mp3");
153	}
154	
155	function hideProgress() {
156	  show(els.progCard, false);
157	  show(els.progDone, false);
158	  els.barFill.style.width = "0%";
159	  els.progPct.textContent = "0%";
160	  els.barWrap.setAttribute("aria-valuenow", "0");
161	  if (pollTimer) { clearInterval(pollTimer); pollTimer = null; }
162	}
163	
164	async function startDownload() {
165	  const url = els.url.value.trim();
166	  if (!url) return;
167	
168	  const payload = { url, type: currentType };
169	  if (currentType === "video") payload.quality = parseInt(els.quality.value, 10) || null;
170	  if (currentType === "mp3") payload.bitrate = parseInt(els.bitrate.value, 10) || 192;
171	
172	  els.dlBtn.disabled = true;
173	  show(els.progCard, true);
174	  show(els.progDone, false);
175	  els.errMsg.textContent = "";
176	  show(els.errMsg, false);
177	  els.progText.textContent = "กำลังรเิ่ม…";
178	  els.barFill.style.width = "0%";
179	  els.progPct.textContent = "0%";
180	  els.barWrap.setAttribute("aria-valuenow", "0");
181	
182	  try {
183	    const res = await fetch("/api/download", {
184	      method: "POST",
185	      headers: { "Content-Type": "application/json" },
186	      body: JSON.stringify(payload),
187	    });
188	    const data = await res.json();
189	    if (!res.ok) throw new Error(data.error || "เริ่มดาวนโหลดไมสำเร็จ");
190	    pollProgress(data.job_id);
191	  } catch (e) {
192	    showError(e.message);
193	  } finally {
194	    els.dlBtn.disabled = false;
195	  }
196	}
197	
198	function pollProgress(jobId) {
199	  if (pollTimer) clearInterval(pollTimer);
200	  pollTimer = setInterval(async () => {
201	    try {
202	      const res = await fetch(`/api/progress/${jobId}`);
203	      const p = await res.json();
204	      if (!res.ok) throw new Error(p.error || "มไมพบ job");
205	
206	      const pct = Math.round(p.percent || 0);
207	      els.progText.textContent = p.status_text || "";
208	      els.progPct.textContent = `${pct}%`;
209	      els.barFill.style.width = `${pct}%`;
210	      els.barWrap.setAttribute("aria-valuenow", String(pct));
211	
212	      if (p.status === "done") {
213	        clearInterval(pollTimer); pollTimer = null;
214	        els.progText.textContent = "เสร็จสิ้น";
215	        els.barFill.style.width = "100%";
216	        els.progPct.textContent = "100%";
217	        els.barWrap.setAttribute("aria-valuenow", "100");
218	        els.saveBtn.href = p.download_url;
219	        show(els.progDone, true);
220	      } else if (p.status === "error") {
221	        clearInterval(pollTimer); pollTimer = null;
222	        showError(p.error || "เกิดข้อผิดพลาด");
223	      }
224	    } catch (e) {
225	      clearInterval(pollTimer); pollTimer = null;
226	      showError(e.message);
227	    }
228	  }, 1000);
229	}
230	
231	function showError(msg) {
232	  els.progText.textContent = "พิดพลาด";
233	  els.errMsg.textContent = msg;
234	  show(els.errMsg, true);
235	}
236	
237	// ---------- bind ----------
238	els.checkBtn.addEventListener("click", checkInfo);
239	els.url.addEventListener("keydown", (e) => { if (e.key === "Enter") checkInfo(); });
240	els.typeSeg.addEventListener("click", (e) => {
241	  const btn = e.target.closest(".seg-btn");
242	  if (btn) setType(btn.dataset.type);
243	});
244	els.dlBtn.addEventListener("click", startDownload);
