    #    (yt-dlp looks for a file named "ffmpeg" in the ffmpeg_location dir,
    #     but imageio-ffmpeg ships it as ffmpeg-win-x86_64-v7.1.exe)
    try:
        import imageio_ffmpeg
        src = imageio_ffmpeg.get_ffmpeg_exe()
