from collections import deque


class Node:
    def __init__(self, val, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def serialize(root):
    if root is None:
        return ""
    queue = deque([root])
    parts = []
    while queue:
        node = queue.popleft()
        if node is None:
            parts.append("null")
        else:
            parts.append(str(node.val))
            queue.append(node.left)
            queue.append(node.right)
    while parts and parts[-1] == "null":
        parts.pop()
    return ",".join(parts)


def deserialize(s):
    if not s:
        return None
    parts = s.split(",")
    root = Node(int(parts[0]))
    queue = deque([root])
    i = 1
    while queue and i < len(parts):
        node = queue.popleft()
        if i < len(parts):
            if parts[i] != "null":
                node.left = Node(int(parts[i]))
                queue.append(node.left)
            i += 1
        if i < len(parts):
            if parts[i] != "null":
                node.right = Node(int(parts[i]))
                queue.append(node.right)
            i += 1
    return root
